/usr/bin/bash -lc 'for f in /workspace/final_answer/trimmed_forward.fastqsanger.gz /workspace/final_answer/trimmed_reverse.fastqsanger.gz; do
  gzip -cd "$f" | awk '"'
    NR%4==2 {seq="'$0}
    NR%4==0 {qual=$0; total++; n=gsub(/N/,"N",seq); low=0; for(i=1;i<=length(qual);i++){if(substr(qual,i,1) < "5") low++}; if(n>5) n_bad++; if(length(seq)<15) short_bad++; if(length(qual)>0 && low/length(qual)*100 > 40) lowq_bad++}
    END {printf "%s total=%d N>5=%d short=%d lowQ>40=%d'"\\n\", FILENAME, total, n_bad, short_bad, lowq_bad}
  ' 
done"

